// Exercise tl::unexpected<E>::value() on a properly-initialized object
// Choose E = int which is trivially comparable and non-void
int e = (int)(*FUZZ_PARAM(unsigned int));
tl::unexpected<int> u(e);
// value() returns const E&; this must always equal the stored error
const int &eref = u.value();
FUZZ_ASSERT(eref == e, "tl::unexpected::value() must return the stored error");

// Create an unexpected via factory with a decayed argument (E = int)
int v = (int)(*FUZZ_PARAM(unsigned int));
auto u = tl::make_unexpected(v);
// Validate the constructed value matches the input
FUZZ_ASSERT(u.value() == v, "tl::make_unexpected should store the forwarded value");

// Cover both overload families: unexpected<E> and expected<T,E>
// 1) unexpected<int> equality
int a = (int)(*FUZZ_PARAM(unsigned int));
int b = (int)(*FUZZ_PARAM(unsigned int));
tl::unexpected<int> ua(a), ub(b);
bool ue_eq = (ua == ub);
FUZZ_ASSERT(ue_eq == (ua.value() == ub.value()), "unexpected== must compare contained errors");

// 2) expected<int,int> equality paths (value/value, error/error, mixed)
int v1 = (int)(*FUZZ_PARAM(unsigned int));
int v2 = (int)(*FUZZ_PARAM(unsigned int));
int e1 = (int)(*FUZZ_PARAM(unsigned int));
int e2 = (int)(*FUZZ_PARAM(unsigned int));
// Build four candidates and pick two scenarios to compare
 tl::expected<int,int> ev1(v1);
 tl::expected<int,int> ev2(v2);
 tl::expected<int,int> ee1(tl::unexpect, e1);
 tl::expected<int,int> ee2(tl::unexpect, e2);

bool eq_vv = (ev1 == ev2);
bool eq_ee = (ee1 == ee2);
bool eq_vm = (ev1 == ee1);
// Basic law: equality is exclusive with inequality
FUZZ_ASSERT(eq_vm == false, "expected== must be false when states differ");
// Consistency checks against underlying semantics
FUZZ_ASSERT(eq_vv == (v1 == v2), "expected== value/value must compare underlying values");
FUZZ_ASSERT(eq_ee == (e1 == e2), "expected== error/error must compare underlying errors");

// Cover both overload families: unexpected<E> and expected<T,E>
// 1) unexpected<int> inequality
int a = (int)(*FUZZ_PARAM(unsigned int));
int b = (int)(*FUZZ_PARAM(unsigned int));
tl::unexpected<int> ua(a), ub(b);
bool ne = (ua != ub);
FUZZ_ASSERT(ne == (ua.value() != ub.value()), "unexpected!= must compare contained errors");

// 2) expected<int,int> inequality mirrors equality
int v1 = (int)(*FUZZ_PARAM(unsigned int));
int v2 = (int)(*FUZZ_PARAM(unsigned int));
int e1 = (int)(*FUZZ_PARAM(unsigned int));
int e2 = (int)(*FUZZ_PARAM(unsigned int));
 tl::expected<int,int> ev1(v1);
 tl::expected<int,int> ev2(v2);
 tl::expected<int,int> ee1(tl::unexpect, e1);
 tl::expected<int,int> ee2(tl::unexpect, e2);

bool ne_vv = (ev1 != ev2);
bool ne_ee = (ee1 != ee2);
bool ne_vm = (ev1 != ee1);
FUZZ_ASSERT(ne_vm == true, "expected!= must be true when states differ");
FUZZ_ASSERT(ne_vv == (v1 != v2), "expected!= value/value must compare underlying values");
FUZZ_ASSERT(ne_ee == (e1 != e2), "expected!= error/error must compare underlying errors");

// unexpected<E> strict weak ordering via underlying error compare; choose E=int
int a = (int)(*FUZZ_PARAM(unsigned int));
int b = (int)(*FUZZ_PARAM(unsigned int));
tl::unexpected<int> ua(a), ub(b);
bool lt = (ua < ub);
FUZZ_ASSERT(lt == (a < b), "unexpected< must compare underlying errors with <");

// unexpected<= via underlying error compare; choose E=int
int a = (int)(*FUZZ_PARAM(unsigned int));
int b = (int)(*FUZZ_PARAM(unsigned int));
tl::unexpected<int> ua(a), ub(b);
bool le = (ua <= ub);
FUZZ_ASSERT(le == (a <= b), "unexpected<= must compare underlying errors with <=");

// unexpected> via underlying error compare; choose E=int
int a = (int)(*FUZZ_PARAM(unsigned int));
int b = (int)(*FUZZ_PARAM(unsigned int));
tl::unexpected<int> ua(a), ub(b);
bool gt = (ua > ub);
FUZZ_ASSERT(gt == (a > b), "unexpected> must compare underlying errors with >");

// unexpected>= via underlying error compare; choose E=int
int a = (int)(*FUZZ_PARAM(unsigned int));
int b = (int)(*FUZZ_PARAM(unsigned int));
tl::unexpected<int> ua(a), ub(b);
bool ge = (ua >= ub);
FUZZ_ASSERT(ge == (a >= b), "unexpected>= must compare underlying errors with >=");

// Exercise and_then on both value and error states
int v = (int)(*FUZZ_PARAM(unsigned int));
int err = (int)(*FUZZ_PARAM(unsigned int));

// Value state
 tl::expected<int,int> ev(v);
 auto f = [](int x) {
   // Return expected<long,int>, value on odd, error on even
   if ((x & 1) != 0) return tl::expected<long,int>(static_cast<long>(x * 2L));
   return tl::expected<long,int>(tl::unexpect, x);
 };
 auto rv = ev.and_then(f);
 bool expected_has = ((v & 1) != 0);
 FUZZ_ASSERT(rv.has_value() == expected_has, "and_then should pass-through value or map to error based on f");

// Error state propagates without invoking f's value path
 tl::expected<int,int> ee(tl::unexpect, err);
 auto re = ee.and_then(f);
 FUZZ_ASSERT(!re.has_value(), "and_then must propagate error unchanged");

// Exercise map (transform) in both value and error states
int v = (int)(*FUZZ_PARAM(unsigned int));
int err = (int)(*FUZZ_PARAM(unsigned int));
 tl::expected<int,int> ev(v);
 tl::expected<int,int> ee(tl::unexpect, err);

// Mapper returning non-void (int -> double)
 auto f_nonvoid = [](int x) { return x * 0.5; };
 auto mv  = ev.map(f_nonvoid);
 auto me1 = ee.map(f_nonvoid);
 FUZZ_ASSERT(mv.has_value(), "map should produce a value when input had a value");
 FUZZ_ASSERT(!me1.has_value(), "map should propagate error unchanged");

// Mapper returning void switches result to expected<void,E>
 bool touched = false;
 auto f_void = [&](int) { touched = true; };
 auto mv2  = ev.map(f_void);
 auto me2  = ee.map(f_void);
 FUZZ_ASSERT(touched, "map(void) must invoke mapper when value is present");
 FUZZ_ASSERT(!me2.has_value(), "map(void) should propagate error unchanged");

// transform is an alias of map; re-run with different lambdas
int v = (int)(*FUZZ_PARAM(unsigned int));
int err = (int)(*FUZZ_PARAM(unsigned int));
 tl::expected<int,int> ev(v);
 tl::expected<int,int> ee(tl::unexpect, err);

 auto f1 = [](int x) { return x + 7; };
 auto tv = ev.transform(f1);
 auto te = ee.transform(f1);
 FUZZ_ASSERT(tv.has_value() && *tv == v + 7, "transform should map value with f");
 FUZZ_ASSERT(!te.has_value(), "transform should propagate error");

// Exercise map_error with both value and error states
int v = (int)(*FUZZ_PARAM(unsigned int));
int err = (int)(*FUZZ_PARAM(unsigned int));
 tl::expected<int,int> ev(v);
 tl::expected<int,int> ee(tl::unexpect, err);

// Error-mapper returning a different error type: int -> long
 auto g_nonvoid = [](int e) { return static_cast<long>(e * 3L + 1L); };
 auto r1 = ee.map_error(g_nonvoid);
 auto r2 = ev.map_error(g_nonvoid);
 FUZZ_ASSERT(!r1.has_value(), "map_error on error should still be an error (with mapped type)");
 FUZZ_ASSERT(r2.has_value() && *r2 == v, "map_error on value should leave the value intact");

// Error-mapper returning void switches error type to tl::monostate
 auto g_void = [](int) { /* no-op */ };
 auto r3 = ee.map_error(g_void);
 FUZZ_ASSERT(!r3.has_value(), "map_error(void) keeps it as error with monostate type");

// transform_error is an alias of map_error
int v = (int)(*FUZZ_PARAM(unsigned int));
int err = (int)(*FUZZ_PARAM(unsigned int));
 tl::expected<int,int> ev(v);
 tl::expected<int,int> ee(tl::unexpect, err);

 auto g = [](int e) { return e - 1; };
 auto te = ee.transform_error(g);
 auto tv = ev.transform_error(g);
 FUZZ_ASSERT(!te.has_value(), "transform_error should map error type/value when in error state");
 FUZZ_ASSERT(tv.has_value() && *tv == v, "transform_error on value should leave the value");

// Exercise or_else with handlers returning expected and void
int v = (int)(*FUZZ_PARAM(unsigned int));
int err = (int)(*FUZZ_PARAM(unsigned int));
 tl::expected<int,int> ev(v);
 tl::expected<int,int> ee(tl::unexpect, err);

// Handler returns expected<int,int>
 auto h_ret_expected = [](int e) {
   if ((e & 1) == 0) return tl::expected<int,int>(42); // recover with a value
   return tl::expected<int,int>(tl::unexpect, e - 1);   // keep as error
 };
 auto r1 = ee.or_else(h_ret_expected);
 // If err even, recovered value 42; else remains error
 if ((err & 1) == 0) {
   FUZZ_ASSERT(r1.has_value() && *r1 == 42, "or_else(expected) should allow recovery to a value");
 } else {
   FUZZ_ASSERT(!r1.has_value(), "or_else(expected) may keep error as directed by handler");
 }
 // Value state should remain untouched
 auto r2 = ev.or_else(h_ret_expected);
 FUZZ_ASSERT(r2.has_value() && *r2 == v, "or_else on value must leave it unchanged");

// Handler returns void
 bool touched = false;
 auto h_void = [&](int){ touched = true; };
 auto r3 = ee.or_else(h_void);
 FUZZ_ASSERT(touched, "or_else(void) must call handler on error");
 // Result remains same object semantics; on error state, still error
 FUZZ_ASSERT(!r3.has_value(), "or_else(void) returns same error-state expected");

// Assign a new value to expected<int,int> (covers both value->value and error->value paths)
