int v2 = (int)(*FUZZ_PARAM(unsigned int));
int e  = (int)(*FUZZ_PARAM(unsigned int));

// Start with value, then assign
 tl::expected<int,int> ev(v1);
 ev = v2;
 FUZZ_ASSERT(ev.has_value() && *ev == v2, "operator= should assign into existing value");

// Start with error, then assign (requires E nothrow-move-constructible; int satisfies)
 tl::expected<int,int> ee(tl::unexpect, e);
 ee = v1;
 FUZZ_ASSERT(ee.has_value() && *ee == v1, "operator= should construct value from U when in error state");

// Emplace a new value T into expected<int,int> from both states
int v1 = (int)(*FUZZ_PARAM(unsigned int));
int v2 = (int)(*FUZZ_PARAM(unsigned int));
int e  = (int)(*FUZZ_PARAM(unsigned int));

// Value state -> replace
 tl::expected<int,int> ev(v1);
 ev.emplace(v2);
 FUZZ_ASSERT(ev.has_value() && *ev == v2, "emplace should reconstruct value in-place from args");

// Error state -> construct value, destroying error
 tl::expected<int,int> ee(tl::unexpect, e);
 ee.emplace(v1);
 FUZZ_ASSERT(ee.has_value() && *ee == v1, "emplace should replace error with constructed value");

// Member swap across all combinations: value<->value, error<->error, value<->error
int v1 = (int)(*FUZZ_PARAM(unsigned int));
int v2 = (int)(*FUZZ_PARAM(unsigned int));
int e1 = (int)(*FUZZ_PARAM(unsigned int));
int e2 = (int)(*FUZZ_PARAM(unsigned int));

// value <-> value
 tl::expected<int,int> a(v1), b(v2);
 a.swap(b);
 FUZZ_ASSERT(a.has_value() && *a == v2, "swap(value,value): a should take b's value");
 FUZZ_ASSERT(b.has_value() && *b == v1, "swap(value,value): b should take a's value");

// error <-> error
 tl::expected<int,int> c(tl::unexpect, e1), d(tl::unexpect, e2);
 c.swap(d);
 FUZZ_ASSERT(!c.has_value() && d.error() == e1, "swap(error,error): d should take c's error");
 FUZZ_ASSERT(!d.has_value() && c.error() == e2, "swap(error,error): c should take d's error");

// value <-> error
 tl::expected<int,int> x(v1), y(tl::unexpect, e1);
 x.swap(y);
 FUZZ_ASSERT(!x.has_value() && x.error() == e1, "swap(value,error): x should become error");
 FUZZ_ASSERT(y.has_value() && *y == v1, "swap(value,error): y should become value");

