import random
import string
from typing import List

# This generator targets inputs for tl::expected<std::string,int> used with operator->().
# FUZZ_PARAM_STR supplies a std::string; any bytes are valid, including nulls.

MAX_SIZE = 4096

def _rand_bytes(rng: random.Random, n: int) -> bytes:
    return bytes(rng.randrange(0, 256) for _ in range(n))

def _pattern_ascii(rng: random.Random, n: int) -> bytes:
    # Build a bytes object from chosen ASCII chars; avoid constructing via bytes(generator of bytes)
    chars = (string.ascii_letters + string.digits + " _-:/.,\n\t").encode('latin1')
    return bytes(chars[rng.randrange(0, len(chars))] for _ in range(n))

def _pattern_repeated(rng: random.Random, n: int) -> bytes:
    motifs = [b"a", b"0", b"\x00", b"\xff", b"ab", b"\x00\x01", b"XYZ", b"\n", b"\r\n", b"\t"]
    motif = rng.choice(motifs)
    if rng.random() < 0.5:
        mlen = rng.randint(1, 8)
        motif = _rand_bytes(rng, mlen)
    if n == 0:
        return b""
    reps = max(1, (n + len(motif) - 1) // max(1, len(motif)))
    data = (motif * reps)[:n]
    return data

def _pattern_binary(rng: random.Random, n: int) -> bytes:
    data = bytearray(n)
    for i in range(n):
        p = rng.random()
        if p < 0.15:
            data[i] = 0x00
        elif p < 0.30:
            data[i] = 0xFF
        elif p < 0.55:
            data[i] = rng.randrange(0x20, 0x7F)  # printable ASCII
        else:
            data[i] = rng.randrange(0, 256)
    return bytes(data)

def _pattern_unicode_like(rng: random.Random, n: int) -> bytes:
    out = bytearray()
    while len(out) < n:
        choice = rng.random()
        if choice < 0.5:
            out.append(rng.randrange(0x20, 0x7F))
        elif choice < 0.7:
            b1 = rng.randrange(0xC2, 0xE0)
            b2 = rng.randrange(0x80, 0xC0)
            out.extend((b1, b2))
        elif choice < 0.85:
            b1 = rng.randrange(0xE0, 0xF0)
            b2 = rng.randrange(0x80, 0xC0)
            b3 = rng.randrange(0x80, 0xC0)
            out.extend((b1, b2, b3))
        elif choice < 0.95:
            b1 = rng.randrange(0xF0, 0xF5)
            b2 = rng.randrange(0x80, 0xC0)
            b3 = rng.randrange(0x80, 0xC0)
            b4 = rng.randrange(0x80, 0xC0)
            out.extend((b1, b2, b3, b4))
        else:
            out.append(rng.randrange(0x80, 0xA0))
    return bytes(out[:n])

def _edge_lengths(rng: random.Random) -> List[int]:
    base = [0, 1, 2, 3, 4, 7, 8, 15, 16, 31, 32, 63, 64, 127, 128, 255, 256, 511, 512, 1023, 1024]
    base.append(rng.randint(0, min(2048, MAX_SIZE)))
    base.append(min(MAX_SIZE, rng.randint(1025, MAX_SIZE)))
    return base

def _compose(rng: random.Random, n: int) -> bytes:
    if n == 0:
        return b""
    segments = []
    remaining = n
    generators = [_pattern_ascii, _pattern_repeated, _pattern_binary, _pattern_unicode_like]
    while remaining > 0:
        gen = rng.choice(generators)
        seg_len = rng.randint(1, remaining)
        segments.append(gen(rng, seg_len))
        remaining -= seg_len
    return b"".join(segments)

def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    strategy = rng.choice([
        "ascii", "repeated", "binary", "unicode", "composed"
    ])

    length = rng.choice(_edge_lengths(rng))

    if strategy == "ascii":
        data = _pattern_ascii(rng, length)
    elif strategy == "repeated":
        data = _pattern_repeated(rng, length)
    elif strategy == "binary":
        data = _pattern_binary(rng, length)
    elif strategy == "unicode":
        data = _pattern_unicode_like(rng, length)
    else:
        data = _compose(rng, length)

    extras = [b"", b"\x00", b"\xff", b"\n", b"\r\n", b" ", b"\t"]
    if rng.random() < 0.4 and len(data) < MAX_SIZE:
        prefix = rng.choice(extras)
        suffix = rng.choice(extras)
        data = (prefix + data + suffix)[:MAX_SIZE]

    return data
